use crate::aap::caps::inference_llm;

struct Node;

/// Clamp a string to at most `max` Unicode scalar values, matching Python's
/// `len()` (character count) semantics used by the `ensures` on `overview`.
fn clamp_chars(s: String, max: usize) -> String {
    if s.chars().count() <= max {
        s
    } else {
        s.chars().take(max).collect()
    }
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Build the material for the model from the kept entries only.
        let mut prompt = String::new();
        prompt.push_str("Date: ");
        prompt.push_str(&info.date);
        prompt.push('\n');
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str("- ");
            prompt.push_str(&e.title);
            prompt.push_str(" :: ");
            prompt.push_str(&e.summary);
            prompt.push('\n');
        }

        let system = "Write a single concise overview paragraph (at most 600 \
                      characters) summarising the day's kept items. Plain prose, \
                      no preamble.";

        let overview = inference_llm::infer(system, &prompt, "digest");

        // ensures len(overview) <= 600
        let overview = clamp_chars(overview, 600);

        // ensures len(date) == 10 — carried straight through from the input,
        // whose requires guarantees len(in1.date) == 10.
        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
